"""Step D3: turn a computed `AnalysisResult` into validated `Hints`.

The model only ever sees a bounded summary of computed values: never the video,
raw landmarks or an identifier. The client is injected, so tests use a fake.
"""

import json
from datetime import UTC, datetime
from typing import Protocol

from pydantic import BaseModel, Field, ValidationError

from common.utils.errors import PermanentError, TransientError
from common.utils.logger import log
from shared.models import Hint, Hints
from worker._1_mediapipe._4_pose_movements import LIMB_JOINTS

#: Upper bound of angle samples sent to the model, whatever the video length.
MAX_PROMPT_FRAMES = 40
#: Upper bound of movements and pauses listed in the prompt.
MAX_PROMPT_MOVEMENTS = 60
MAX_PROMPT_PAUSES = 20
#: A limb measured on fewer frames than this share is flagged unreliable.
MIN_COVERAGE = 0.7


class DraftHint(Hint):
    """A hint as written by the model (the generated `Hint` does not bound `priority`)."""

    priority: int = Field(ge=1, le=5)


class HintsDraft(BaseModel):
    """What the model must return. `model` and `generated_at` are set by the code."""

    summary: str
    items: list[DraftHint]


class JsonClient(Protocol):
    """Anything that answers a prompt with a JSON object (see `services.llm.LLM`)."""

    def generate_json(self, prompt: str) -> dict: ...


def _coverage(frames: list[dict]) -> dict[str, dict]:
    """Share of frames where each limb speed was measured, and the longest blind stretch."""
    out = {}
    for limb, joint in LIMB_JOINTS.items():
        measured = [joint in (f.get("speeds") or {}) for f in frames]
        gap = longest = 0
        for ok in measured:
            gap = 0 if ok else gap + 1
            longest = max(longest, gap)
        ratio = sum(measured) / len(measured) if measured else 0.0
        out[limb] = {"measured_ratio": round(ratio, 2), "longest_gap_frames": longest}
    return out


def _spread(items: list, limit: int) -> list:
    """Keep at most ``limit`` items, evenly spread, order preserved."""
    if len(items) <= limit:
        return items
    return [items[i * len(items) // limit] for i in range(limit)]


def _sample_frames(frames: list[dict], movements: list[dict]) -> list[dict]:
    """Angles at the start and end of each movement, plus a regular sample, up to the cap."""
    by_number = {f["frame"]: f for f in frames if f.get("pose_detected")}
    key = sorted({n for m in movements for n in (m["start_frame"], m["end_frame"]) if n in by_number})
    key = _spread(key, MAX_PROMPT_FRAMES // 2)
    regular = _spread(sorted(by_number), MAX_PROMPT_FRAMES - len(key))
    return [
        {"frame": n, "time_ms": by_number[n]["timestamp_ms"], "angles": by_number[n]["angles"]}
        for n in sorted(set(key) | set(regular))
    ]


def summarize(result: dict) -> dict:
    """Reduce an `AnalysisResult` dict to a small, identifier-free summary (pure).

    Contains the video facts, per-limb measurement coverage, metrics, movements,
    pauses and a bounded sample of joint angles. Never raw landmarks.
    """
    frames = result.get("frames", [])
    movements = result.get("movements") or []
    pauses = result.get("pauses") or []
    coverage = _coverage(frames)
    unreliable = [k for k, v in coverage.items() if v["measured_ratio"] < MIN_COVERAGE]
    metrics = dict(result.get("metrics") or {})
    if metrics.get("avg_speed"):
        # An average over a few measured frames says nothing: do not hand it to the model.
        bad = {LIMB_JOINTS[k] for k in unreliable}
        metrics["avg_speed"] = {j: v for j, v in metrics["avg_speed"].items() if j not in bad}
    summary = {
        "video": {
            "fps": result.get("fps"),
            "frames": len(frames),
            "first_frame": frames[0]["frame"] if frames else None,
            "last_frame": frames[-1]["frame"] if frames else None,
        },
        "measurement_coverage": coverage,
        "unreliable_limbs": unreliable,
        "metrics": metrics or None,
        "movements": [
            {
                "limb": m["limb"],
                "start_frame": m["start_frame"],
                "end_frame": m["end_frame"],
                "duration_ms": m["end_ms"] - m["start_ms"],
            }
            for m in _spread(movements, MAX_PROMPT_MOVEMENTS)
        ],
        "movements_total": len(movements),
        "pauses": [
            {"start_frame": p["start_frame"], "end_frame": p["end_frame"], "duration_ms": p["end_ms"] - p["start_ms"]}
            for p in _spread(pauses, MAX_PROMPT_PAUSES)
        ],
        "pauses_total": len(pauses),
        "angle_samples": _sample_frames(frames, movements),
    }
    return summary


def build_prompt(summary: dict) -> str:
    """Build the prompt sent to the model (pure)."""
    schema = json.dumps(HintsDraft.model_json_schema(), ensure_ascii=False)
    return (
        "You are an expert climbing coach. Below is a summary of computed 2D body measurements "
        "from one video of a climber (no image is provided).\n\n"
        "Rules:\n"
        "1. Write `summary`, every `title` and every `description` in FRENCH.\n"
        "2. Use only the data below. You cannot see the wall: never invent holds, route features "
        "or what the climber grabs.\n"
        "3. Measurement quality comes first. `measurement_coverage` gives, per limb, the share of "
        "frames where its speed was measured (`measured_ratio`) and the longest stretch without "
        "any measure (`longest_gap_frames`). `unreliable_limbs` lists the limbs measured on too "
        "few frames. For an unreliable limb, never draw conclusions about it (no speed, "
        "movement-count, hesitation or technique advice), and never claim that it did not move: "
        "no measure is not no movement. A movement ending next to a gap may be cut short. If a "
        "limb is unreliable, you may say so in `summary`.\n"
        "4. The same caution applies to any period: do not state that nothing happened where "
        "there is no measure. An empty `pauses` list does not mean the climber never rested.\n"
        "5. Give at most 5 hints, most important first. `priority` is 1 (minor) to 5 (critical). "
        "`frame_start` and `frame_end` must be frames between `first_frame` and `last_frame`, "
        "taken from the data below, or null. Cite those frames in the description when relevant.\n"
        "6. Speeds are in torso lengths per second. Angles are in degrees.\n"
        "7. Answer with one JSON object only, matching this JSON schema. Do not add `model` or "
        "`generated_at`.\n\n"
        f"JSON schema:\n{schema}\n\n"
        f"Data:\n{json.dumps(summary, ensure_ascii=False)}\n"
    )


class PoseAdvice:
    def __init__(self, client: JsonClient, model: str):
        """Args:
        client: Object with ``generate_json(prompt) -> dict``.
        model: Model name stored in `Hints.model`.
        """
        self.client = client
        self.model = model

    def process(self, result: dict) -> Hints:
        """Ask the model for advice on ``result`` and return validated `Hints`.

        Raises:
            PermanentError: No pose was detected (the model is not called).
            TransientError: The answer does not match the schema, or the client failed.
        """
        if not any(f.get("pose_detected") for f in result.get("frames", [])):
            raise PermanentError("no pose detected: nothing to advise on")
        summary = summarize(result)
        try:
            draft = HintsDraft.model_validate(self.client.generate_json(build_prompt(summary)))
        except ValidationError as e:
            log.warning("LLM answer rejected: %s", e)
            raise TransientError("LLM answer does not match the Hints schema") from e
        first, last = summary["video"]["first_frame"], summary["video"]["last_frame"]
        items = [Hint.model_validate(_clamp(h.model_dump(), first, last)) for h in draft.items]
        return Hints(summary=draft.summary, items=items, model=self.model, generated_at=datetime.now(UTC))


def _clamp(hint: dict, first: int, last: int) -> dict:
    """Null out frames outside the video, and both when the range is inverted."""
    for k in ("frame_start", "frame_end"):
        v = hint.get(k)
        if v is not None and not first <= v <= last:
            log.warning("Hint %r: %s=%s outside frames %s-%s, dropped", hint["title"], k, v, first, last)
            hint[k] = None
    s, e = hint.get("frame_start"), hint.get("frame_end")
    if s is not None and e is not None and s > e:
        log.warning("Hint %r: frame_start > frame_end, both dropped", hint["title"])
        hint["frame_start"] = hint["frame_end"] = None
    return hint
